#include <fstream>
#include <stdexcept>
#include <string>

namespace {
using SectionsType = /* 型定義 */;
using KeysType = /* 型定義 */;
using ValueType = /* 型定義 */;
}

class INIReader {
public:
    SectionsType Sections() const;
    KeysType Keys(const std::string& section) const;
    ValueType Get(const std::string& section, const std::string& key) const;
};

class INIWriter {
public:
    INIWriter() = default;

    static void write(const std::string& filepath, const INIReader& reader, const bool overwrite = false);
};

void INIWriter::write(const std::string& filepath, const INIReader& reader, const bool overwrite) {
    if (!overwrite && std::ifstream{filepath}) {
        throw std::runtime_error("file already exists.");
    }

    std::ofstream out{filepath};
    if (!out) {
        throw std::runtime_error("cannot open output file.");
    }

    for (const auto& section : reader.Sections()) {
        out << "[" + section + "]\n";
        for (const auto& key : reader.Keys(section)) {
            const auto value = reader.Get(section, key);
            out << key + "=" + value + "\n";
        }
    }
}
